-- DIBUAT OTOMATIS oleh `pnpm content:sql` dari content/*.json dan messages/id.json. Jangan disunting manual.
-- Upsert idempoten: aman dijalankan ulang. Baris yang dihapus dari konten TIDAK dihapus dari DB
-- (jawaban siswa tetap utuh); tandai saja di konten.

on conflict (slug) do update set title = excluded.title, sort_order = excluded.sort_order,
  learning_objectives = excluded.learning_objectives, intro = excluded.intro;

on conflict (code) do update set statement = excluded.statement,
  scientific_explanation = excluded.scientific_explanation, unit_id = excluded.unit_id;

on conflict (unit_id, slug) do update set title = excluded.title, sort_order = excluded.sort_order,
  required = excluded.required, license = excluded.license, attribution = excluded.attribution,
  source_url = excluded.source_url, review_status = excluded.review_status;

on conflict (key) do update set unit_id = excluded.unit_id, sort_order = excluded.sort_order, stem = excluded.stem,
  options = excluded.options, correct_key = excluded.correct_key, reveal_text = excluded.reveal_text,
  misconception_code = excluded.misconception_code, misconception_option = excluded.misconception_option;
