insert into public.units (slug, title, sort_order, learning_objectives, intro) values
  ('u1', 'Benda langit', 1, '["Membedakan bintang, planet, satelit alami, planet kerdil, komet, dan asteroid.","Menjelaskan bahwa Matahari adalah bintang yang membuat cahaya sendiri.","Menjelaskan bahwa Bulan memantulkan cahaya Matahari."]'::jsonb, 'Matahari, planet, planet kerdil, komet, dan asteroid.'),
  ('u2', 'Planet dan karakteristiknya', 2, '["Membandingkan ukuran, suhu, atmosfer, dan permukaan delapan planet.","Menjelaskan mengapa Venus lebih panas daripada Merkurius."]'::jsonb, 'Delapan planet: atmosfer, suhu, ukuran, dan permukaan.'),
  ('u3', 'Zona planet', 3, '["Mengurutkan planet dari yang terdekat sampai terjauh dari Matahari.","Mengelompokkan planet menjadi planet dalam dan planet luar beserta cirinya.","Menunjukkan letak sabuk asteroid sebagai pembatas kedua kelompok."]'::jsonb, 'Planet dalam yang berbatu dan planet luar yang raksasa.'),
  ('u4', 'Meteoroid, meteor, meteorit', 4, '["Membedakan meteoroid, meteor, dan meteorit berdasarkan tempatnya.","Menjelaskan bahwa ''bintang jatuh'' adalah meteor, bukan bintang."]'::jsonb, 'Perjalanan batuan angkasa sampai ke permukaan Bumi.'),
  ('u5', 'Rotasi dan revolusi Bumi', 5, '["Menjelaskan bahwa siang dan malam terjadi karena rotasi Bumi.","Menjelaskan bahwa revolusi Bumi memerlukan sekitar 365¼ hari.","Menjelaskan bahwa musim disebabkan oleh kemiringan sumbu Bumi, bukan jarak ke Matahari."]'::jsonb, 'Kenapa ada siang, malam, dan musim.'),
  ('u6', 'Gerhana', 6, '["Menunjukkan posisi Matahari, Bulan, dan Bumi saat gerhana Matahari dan gerhana Bulan.","Menjelaskan bayangan siapa yang jatuh ke mana pada setiap gerhana.","Menyebutkan cara aman mengamati gerhana Matahari."]'::jsonb, 'Posisi Matahari, Bulan, dan Bumi saat gerhana.')
insert into public.misconception_targets (code, statement, scientific_explanation, unit_id) values
  ('MK-U1-A', 'Bulan membuat cahayanya sendiri, seperti Matahari.', 'Bulan tidak membuat cahaya. Bulan memantulkan cahaya Matahari.', (select id from public.units where slug = 'u1')),
  ('MK-U1-B', 'Bintang adalah benda kecil, berbeda dengan Matahari.', 'Matahari adalah bintang. Bintang lain tampak kecil karena letaknya sangat jauh.', (select id from public.units where slug = 'u1')),
  ('MK-U2-A', 'Planet yang paling dekat dengan Matahari pasti paling panas.', 'Venus paling panas karena atmosfernya yang tebal menahan panas, walaupun Merkurius lebih dekat ke Matahari.', (select id from public.units where slug = 'u2')),
  ('MK-U3-A', 'Semua planet punya permukaan berbatu seperti Bumi.', 'Hanya planet dalam yang berbatu. Planet luar adalah raksasa gas dan es tanpa permukaan keras.', (select id from public.units where slug = 'u3')),
  ('MK-U3-B', 'Planet dalam dan planet luar ukurannya sama atau tercampur.', 'Planet dalam berukuran kecil dan berbatu; planet luar berukuran raksasa. Sabuk asteroid memisahkan keduanya.', (select id from public.units where slug = 'u3')),
  ('MK-U4-A', 'Semua batuan dari luar angkasa jatuh sampai ke tanah.', 'Hampir semua meteoroid habis terbakar di atmosfer. Hanya sisa yang sampai ke tanah yang disebut meteorit.', (select id from public.units where slug = 'u4')),
  ('MK-U5-A', 'Siang dan malam terjadi karena Matahari mengelilingi Bumi; Matahari menyinari seluruh Bumi sekaligus.', 'Bumi berotasi. Sisi yang menghadap Matahari mengalami siang, sisi yang membelakangi mengalami malam.', (select id from public.units where slug = 'u5')),
  ('MK-U5-B', 'Musim panas terjadi saat Bumi paling dekat dengan Matahari.', 'Musim disebabkan kemiringan sumbu Bumi. Bumi justru paling dekat ke Matahari saat belahan utara mengalami musim dingin.', (select id from public.units where slug = 'u5')),
  ('MK-U6-A', 'Gerhana Bulan terjadi karena awan atau benda lain menutupi Bulan.', 'Saat gerhana Bulan, bayangan Bumi jatuh ke Bulan karena Bumi berada di antara Matahari dan Bulan.', (select id from public.units where slug = 'u6')),
  ('MK-U6-B', 'Saat gerhana Matahari, Bumi yang menghalangi cahaya Matahari.', 'Saat gerhana Matahari, Bulan yang berada di antara Matahari dan Bumi menghalangi cahaya.', (select id from public.units where slug = 'u6'))
