insert into public.prediction_items (key, unit_id, sort_order, stem, options, correct_key, reveal_text, misconception_code, misconception_option) values
  ('u1-cahaya-bulan', (select id from public.units where slug = 'u1'), 0, 'Bulan tampak terang di langit malam. Menurutmu, dari mana cahaya Bulan berasal?', '[{"key":"A","text":"Bulan membuat cahayanya sendiri."},{"key":"B","text":"Bulan memantulkan cahaya Matahari."},{"key":"C","text":"Bulan memantulkan cahaya bintang-bintang."}]'::jsonb, 'B', 'Ternyata Bulan tidak membuat cahaya sendiri. Bulan bersinar karena memantulkan cahaya Matahari.', 'MK-U1-A', 'A'),
  ('u1-bintang-dekat', (select id from public.units where slug = 'u1'), 1, 'Bayangkan kamu terbang mendekati sebuah bintang yang tampak kecil di langit malam. Bintang itu akan tampak seperti apa?', '[{"key":"A","text":"Tetap kecil seperti titik."},{"key":"B","text":"Sangat besar dan terang, seperti Matahari."},{"key":"C","text":"Tidak bercahaya lagi."}]'::jsonb, 'B', 'Ternyata Matahari juga bintang. Bintang lain tampak kecil hanya karena letaknya sangat jauh.', 'MK-U1-B', 'A'),
  ('u2-merkurius-venus', (select id from public.units where slug = 'u2'), 0, 'Merkurius adalah planet terdekat dari Matahari, sedangkan Venus ada di urutan kedua. Menurutmu, bagaimana suhu rata-rata permukaan keduanya?', '[{"key":"A","text":"Merkurius lebih panas karena lebih dekat ke Matahari."},{"key":"B","text":"Venus lebih panas."},{"key":"C","text":"Suhu keduanya sama."}]'::jsonb, 'B', 'Ternyata Venus lebih panas, sekitar 464 °C, walaupun Merkurius lebih dekat. Atmosfer Venus yang tebal menahan panas.', 'MK-U2-A', 'A'),
  ('u3-mendarat-jupiter', (select id from public.units where slug = 'u3'), 0, 'Seandainya sebuah wahana mendarat di Jupiter, di atas apa wahana itu akan berada?', '[{"key":"A","text":"Tanah berbatu yang keras, seperti di Bumi."},{"key":"B","text":"Tidak ada tanah keras; yang ada lapisan gas tebal."},{"key":"C","text":"Lautan air seperti di Bumi."}]'::jsonb, 'B', 'Ternyata Jupiter tidak punya permukaan keras. Jupiter dan Saturnus adalah raksasa gas.', 'MK-U3-A', 'A'),
  ('u3-ukuran-kelompok', (select id from public.units where slug = 'u3'), 1, 'Dibandingkan planet-planet yang jauh dari Matahari, planet-planet yang dekat dengan Matahari ukurannya…', '[{"key":"A","text":"lebih besar."},{"key":"B","text":"lebih kecil."},{"key":"C","text":"sama besar."}]'::jsonb, 'B', 'Ternyata planet dalam jauh lebih kecil. Bumi, planet dalam terbesar, masih lebih kecil daripada Neptunus, planet luar terkecil.', 'MK-U3-B', 'C'),
  ('u4-nasib-batuan', (select id from public.units where slug = 'u4'), 0, 'Setiap hari banyak batuan kecil dari luar angkasa masuk ke lapisan udara Bumi. Menurutmu, apa yang terjadi pada kebanyakan batuan itu?', '[{"key":"A","text":"Semuanya jatuh ke tanah."},{"key":"B","text":"Kebanyakan habis terbakar di udara."},{"key":"C","text":"Memantul kembali ke luar angkasa."}]'::jsonb, 'B', 'Ternyata hampir semua batuan itu habis terbakar di atmosfer dan tampak sebagai meteor. Hanya sisanya yang sampai ke tanah yang disebut meteorit.', 'MK-U4-A', 'A'),
  ('u5-sisi-berlawanan', (select id from public.units where slug = 'u5'), 0, 'Saat di Indonesia siang hari, bagaimana keadaan di tempat yang letaknya tepat di sisi Bumi yang berlawanan?', '[{"key":"A","text":"Juga siang, karena Matahari menyinari seluruh Bumi sekaligus."},{"key":"B","text":"Malam hari."},{"key":"C","text":"Sore hari, Matahari sedang terbenam."}]'::jsonb, 'B', 'Ternyata cahaya Matahari hanya mengenai separuh Bumi. Saat Indonesia siang, sisi yang berlawanan sedang malam.', 'MK-U5-A', 'A'),
  ('u5-dekat-januari', (select id from public.units where slug = 'u5'), 1, 'Bumi berada paling dekat dengan Matahari setiap awal Januari. Menurutmu, musim apa yang sedang terjadi di belahan Bumi utara, misalnya di Jepang?', '[{"key":"A","text":"Musim panas, karena Bumi paling dekat ke Matahari."},{"key":"B","text":"Musim dingin."},{"key":"C","text":"Tidak ada musim."}]'::jsonb, 'B', 'Ternyata saat itu belahan utara mengalami musim dingin. Musim disebabkan kemiringan sumbu Bumi, bukan jaraknya ke Matahari.', 'MK-U5-B', 'A'),
  ('u6-penutup-bulan', (select id from public.units where slug = 'u6'), 0, 'Saat gerhana Bulan, Bulan purnama menjadi gelap atau kemerahan. Menurutmu, apa yang menutupi Bulan?', '[{"key":"A","text":"Awan tebal di langit."},{"key":"B","text":"Bayangan Bumi."},{"key":"C","text":"Bayangan Matahari."}]'::jsonb, 'B', 'Ternyata yang menutupi Bulan adalah bayangan Bumi. Bumi berada di antara Matahari dan Bulan.', 'MK-U6-A', 'A'),
  ('u6-penghalang-matahari', (select id from public.units where slug = 'u6'), 1, 'Saat gerhana Matahari total, siang hari mendadak gelap sebentar. Menurutmu, benda apa yang menghalangi cahaya Matahari?', '[{"key":"A","text":"Bumi."},{"key":"B","text":"Bulan."},{"key":"C","text":"Awan hitam."}]'::jsonb, 'B', 'Ternyata yang menghalangi adalah Bulan. Bulan lewat di antara Matahari dan Bumi, lalu bayangannya jatuh ke Bumi.', 'MK-U6-B', 'A')
